    """Directory holding the project's compose files."""
    if name:
        base = ctx.runtime.get("projects_path") or os.path.join(root_dir(os.environ), "sites")
        return os.path.join(os.path.expanduser(str(base)), name), False
    if ctx.runtime.get("path"):
        return os.path.join(ctx.cwd, os.path.expanduser(str(ctx.runtime["path"]))), False
    return ctx.cwd, True


def config(ctx, args, assoc):
    directory, search_parents = _project_dir(ctx, args[0] if args else None)
    loaded = ctx.config
    base_dirs = [ctx.cwd, directory]
    for path in (getattr(loaded, "project_path", None), getattr(loaded, "global_path", None)):
        if path:
            base_dirs.append(os.path.dirname(os.path.abspath(path)))
    files = container.compose_files(directory, ctx.runtime.get("custom-compose"), ctx.output,
