    except OSError as exc:
        raise AppctlError(f"Cannot chmod {source}.") from exc
    try:
        os.replace(source, target)
    except OSError as exc:
        raise AppctlError(f"Cannot move {source} to {target} ({exc.strerror or exc}).") from exc


